CREATE TABLE public.date_calendar_settings (tenant_id uuid PRIMARY KEY, bosque_closed text NOT NULL DEFAULT '', bosque_interest text NOT NULL DEFAULT '', vila_closed text NOT NULL DEFAULT '', vila_interest text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.date_calendar_settings TO authenticated;
GRANT ALL ON public.date_calendar_settings TO service_role;
ALTER TABLE public.date_calendar_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY date_settings_read ON public.date_calendar_settings FOR SELECT TO authenticated USING (tenant_id = private.current_tenant_id());
CREATE TABLE public.date_holidays (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, holiday_date date NOT NULL, name text NOT NULL, UNIQUE(tenant_id,holiday_date));
GRANT SELECT ON public.date_holidays TO authenticated;
GRANT ALL ON public.date_holidays TO service_role;
ALTER TABLE public.date_holidays ENABLE ROW LEVEL SECURITY;
CREATE POLICY date_holidays_read ON public.date_holidays FOR SELECT TO authenticated USING (tenant_id = private.current_tenant_id());
CREATE TABLE public.date_personal_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, opportunity_id uuid NOT NULL REFERENCES public.opportunities(id), token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
GRANT ALL ON public.date_personal_links TO service_role;
ALTER TABLE public.date_personal_links ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.date_interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, opportunity_id uuid NOT NULL REFERENCES public.opportunities(id), link_id uuid NOT NULL REFERENCES public.date_personal_links(id), action text NOT NULL CHECK (action IN ('abriu','viu_opcao','escolheu_data','entrou_fila','mudou_casa','falou_equipe')), house text CHECK (house IN ('bosque','vila')), party_date date, slot text CHECK (slot IN ('almoco','jantar')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.date_interactions TO authenticated;
GRANT ALL ON public.date_interactions TO service_role;
ALTER TABLE public.date_interactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY date_interactions_read ON public.date_interactions FOR SELECT TO authenticated USING (tenant_id = private.current_tenant_id());
CREATE INDEX date_interactions_op_idx ON public.date_interactions(opportunity_id,created_at);
CREATE TABLE public.date_calendar_cache (tenant_id uuid NOT NULL, calendar_id text NOT NULL, fetched_at timestamptz NOT NULL, events jsonb NOT NULL, PRIMARY KEY(tenant_id,calendar_id));
GRANT ALL ON public.date_calendar_cache TO service_role;
ALTER TABLE public.date_calendar_cache ENABLE ROW LEVEL SECURITY;